15	const sandwichInput = `{"chainId":"1","blockHash":"0xa","blockNumber":10,"swaps":[{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},{"TxHash":"0xvictim","Pool":"p1","Trader":"user","In":200,"Out":188,"GasPrice":10,"Index":1},{"TxHash":"0xback","Pool":"p1","Trader":"bot","In":480,"Out":505,"GasPrice":80,"Index":2}]}`
16	
17	func replay(t *testing.T, dir, input string) []Report {
18		t.Helper()
19		reports, err := Replay(strings.NewReader(input), dir)
20		if err != nil {
21			t.Fatalf("Replay: %v", err)
22		}
23		return reports
24	}
25	
26	func TestReplaySandwichReport(t *testing.T) {
27		dir := t.TempDir()
28		reports := replay(t, dir, sandwichInput)
29		if len(reports) != 1 {
30			t.Fatalf("got %d reports, want 1", len(reports))
31		}
32		r := reports[0]
33		if r.ChainID != "1" || r.BlockHash != "0xa" || r.BlockNumber != 10 {
34			t.Fatalf("bad identity: %+v", r)
35		}
36		if r.SwapCount != 3 {
37			t.Fatalf("SwapCount = %d, want 3", r.SwapCount)
38		}
39		if len(r.Findings) != 1 {
40			t.Fatalf("got %d findings, want 1", len(r.Findings))
41		}
42		f := r.Findings[0]
43		if f.Kind != "sandwich" || f.Severity != 3 || f.TxHash != "0xvictim" {
44			t.Fatalf("bad finding: %+v", f)
45		}
46		if len(f.Evidence) != 3 {
47			t.Fatalf("evidence has %d swaps, want 3", len(f.Evidence))
48		}
49		wantOrder := []string{"0xfront", "0xvictim", "0xback"}
50		for i, want := range wantOrder {
51			if f.Evidence[i].TxHash != want {
52				t.Fatalf("evidence[%d].TxHash = %s, want %s", i, f.Evidence[i].TxHash, want)
53			}
54		}
55		if f.Evidence[0].GasPrice != 90 || f.Evidence[1].Trader != "user" || f.Evidence[2].In != 480 {
56			t.Fatalf("evidence lost raw fields: %+v", f.Evidence)
57		}
58	}
59	
60	func TestReplayDisplacementIncludesLastSwap(t *testing.T) {
61		dir := t.TempDir()
62		input := `{"chainId":"1","blockHash":"0xb","blockNumber":11,"swaps":[{"TxHash":"0xbig","Pool":"p1","Trader":"whale","In":1,"Out":1,"GasPrice":30,"Index":0},{"TxHash":"0xsmall","Pool":"p1","Trader":"user","In":1,"Out":1,"GasPrice":10,"Index":1}]}`
63		reports := replay(t, dir, input)
64		if len(reports[0].Findings) != 1 {
65			t.Fatalf("got %d findings, want 1", len(reports[0].Findings))
66		}
67		f := reports[0].Findings[0]
68		if f.Kind != "displacement" || f.Severity != 2 || f.TxHash != "0xsmall" {
69			t.Fatalf("bad finding: %+v", f)
70		}
71		if len(f.Evidence) != 2 || f.Evidence[0].TxHash != "0xbig" || f.Evidence[1].TxHash != "0xsmall" {
72			t.Fatalf("bad displacement evidence: %+v", f.Evidence)
73		}
74	}
75	
76	func TestReplayGasPriceEdges(t *testing.T) {
77		dir := t.TempDir()
78		input := fmt.Sprintf(`{"chainId":"1","blockHash":"0xc","blockNumber":12,"swaps":[{"TxHash":"0xg1","Pool":"zero","Trader":"a","In":0,"Out":0,"GasPrice":1,"Index":0},{"TxHash":"0xg2","Pool":"zero","Trader":"b","In":0,"Out":0,"GasPrice":0,"Index":1},{"TxHash":"0xg3","Pool":"max","Trader":"a","In":0,"Out":0,"GasPrice":%[1]d,"Index":2},{"TxHash":"0xg4","Pool":"max","Trader":"b","In":0,"Out":0,"GasPrice":%[1]d,"Index":3},{"TxHash":"0xg5","Pool":"huge","Trader":"a","In":0,"Out":0,"GasPrice":%[1]d,"Index":4},{"TxHash":"0xg6","Pool":"huge","Trader":"b","In":0,"Out":0,"GasPrice":100,"Index":5}]}`, math.MaxInt64)
79		reports := replay(t, dir, input)
80		got := map[string]string{}
81		for _, f := range reports[0].Findings {
82			got[f.TxHash] = f.Kind
83		}
84		// victim gas 0: any positive front gas dominates.
85		if got["0xg2"] != "displacement" {
86			t.Fatalf("0xg2 = %q, want displacement", got["0xg2"])
87		}
88		// victim gas MaxInt64: 2x would overflow, must not flag.
89		if _, flagged := got["0xg4"]; flagged {
90			t.Fatalf("0xg4 must not be flagged (overflow)")
91		}
92		// front gas MaxInt64 vs victim 100: dominates without overflow.
93		if got["0xg6"] != "displacement" {
94			t.Fatalf("0xg6 = %q, want displacement", got["0xg6"])
95		}
96		if len(got) != 2 {
97			t.Fatalf("unexpected findings: %v", got)
98		}
99	}
100	
101	func TestReplayFindingsSorted(t *testing.T) {
102		dir := t.TempDir()
103		input := `{"chainId":"1","blockHash":"0xd","blockNumber":13,"swaps":[{"TxHash":"0xza","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":99,"Index":0},{"TxHash":"0xzb","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},{"TxHash":"0xf1","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":50,"Index":2},{"TxHash":"0xv1","Pool":"p2","Trader":"user","In":1,"Out":1,"GasPrice":10,"Index":3},{"TxHash":"0xb1","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":40,"Index":4},{"TxHash":"0xaa","Pool":"p3","Trader":"w","In":1,"Out":1,"GasPrice":99,"Index":5},{"TxHash":"0xab","Pool":"p3","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":6}]}`
104		findings := replay(t, dir, input)[0].Findings
105		if len(findings) != 3 {
106			t.Fatalf("got %d findings, want 3", len(findings))
107		}
108		// severity 3 first, then severity 2 ordered by tx hash ascending.
109		if findings[0].Kind != "sandwich" || findings[0].TxHash != "0xv1" {
110			t.Fatalf("findings[0] = %+v", findings[0])
111		}
112		if findings[1].TxHash != "0xab" || findings[2].TxHash != "0xzb" {
113			t.Fatalf("severity-2 findings not sorted by hash: %+v", findings[1:])
114		}
115		for _, f := range findings[1:] {
116			if f.Severity != 2 {
117				t.Fatalf("severity order broken: %+v", findings)
118			}
119		}
120	}
121	
122	func TestReplayDedupAndPermutation(t *testing.T) {
123		dir := t.TempDir()
124		input := `{"chainId":"1","blockHash":"0xe","blockNumber":20,"swaps":[{"TxHash":"0xs1","Pool":"p","Trader":"a","In":1,"Out":2,"GasPrice":5,"Index":0},{"TxHash":"0xs2","Pool":"p","Trader":"b","In":3,"Out":4,"GasPrice":6,"Index":1},{"TxHash":"0xs1","Pool":"p","Trader":"a","In":1,"Out":2,"GasPrice":5,"Index":0}]}` + "\n" +
125			`{"chainId":"1","blockHash":"0xe","blockNumber":20,"swaps":[{"TxHash":"0xs2","Pool":"p","Trader":"b","In":3,"Out":4,"GasPrice":6,"Index":1},{"TxHash":"0xs1","Pool":"p","Trader":"a","In":1,"Out":2,"GasPrice":5,"Index":0}]}` + "\n"
126		reports := replay(t, dir, input)
127		if len(reports) != 1 {
128			t.Fatalf("permuted duplicate block produced %d reports, want 1", len(reports))
129		}
130		if reports[0].SwapCount != 2 {
131			t.Fatalf("SwapCount = %d, want 2 after dedup", reports[0].SwapCount)
132		}
133		data, err := readArchive(dir)
134		if err != nil {
135			t.Fatal(err)
136		}
137		if len(data.Records) != 1 {
138			t.Fatalf("archive holds %d records, want 1", len(data.Records))
139		}
140	}
141	
142	func TestReplayEmptySwapsAndBlankLines(t *testing.T) {
143		dir := t.TempDir()
144		input := "\n  \n{\"chainId\":\"1\",\"blockHash\":\"0xf\",\"blockNumber\":1,\"swaps\":[]}\n\n"
145		reports := replay(t, dir, input)
146		if len(reports) != 1 {
147			t.Fatalf("got %d reports, want 1", len(reports))
148		}
149		if reports[0].SwapCount != 0 || len(reports[0].Findings) != 0 {
150			t.Fatalf("empty block report wrong: %+v", reports[0])
151		}
152		// Empty findings must serialize as [], not null.
153		raw, err := Query(dir, "1", "0xf")
154		if err != nil {
155			t.Fatal(err)
156		}
157		if raw.Findings == nil {
158			t.Fatal("findings must be an empty array, not null")
159		}
160	}
161	
162	func TestReplayValidationErrors(t *testing.T) {
163		cases := []struct {
164			name  string
165			input string
166			line  int
167		}{
168			{"bad json", `{"chainId":`, 1},
169			{"trailing garbage", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[]} extra`, 1},
170			{"empty chainId", `{"chainId":"","blockHash":"0x","blockNumber":1,"swaps":[]}`, 1},
