174			{"empty txhash", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":0,"Index":0}]}`, 1},
175			{"empty pool", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"","Trader":"t","In":0,"Out":0,"GasPrice":0,"Index":0}]}`, 1},
176			{"empty trader", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"","In":0,"Out":0,"GasPrice":0,"Index":0}]}`, 1},
177			{"negative gas", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":-5,"Index":0}]}`, 1},
178			{"negative index", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":0,"Index":-1}]}`, 1},
179			{"fractional gas", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":1.5,"Index":0}]}`, 1},
180			{"conflicting duplicate tx", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":1,"Index":0},{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":2,"Index":0}]}`, 1},
181			{"shared index", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":1,"Index":0},{"TxHash":"0x2","Pool":"p","Trader":"u","In":0,"Out":0,"GasPrice":1,"Index":0}]}`, 1},
182			{"error on later line", "{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[]}\n\nnot json", 3},
183		}
184		for _, tc := range cases {
185			t.Run(tc.name, func(t *testing.T) {
186				dir := t.TempDir()
187				_, err := Replay(strings.NewReader(tc.input), dir)
188				if err == nil {
189					t.Fatal("expected error")
