func TestReplayMultiBlockOrder(t *testing.T) {
	dir := t.TempDir()
	input := "{\"chainId\":\"1\",\"blockHash\":\"0x1\",\"blockNumber\":1,\"swaps\":[]}\n" +
		"{\"chainId\":\"1\",\"blockHash\":\"0x2\",\"blockNumber\":2,\"swaps\":[]}\n" +
