func TestVersionOpsBusyArchive(t *testing.T) {
	dir := t.TempDir()
	if err := RegisterVersion(dir, v1()); err != nil {
		t.Fatal(err)
	}
	lock, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		t.Fatal(err)
	}
